body:
{
 "version": "schemaxis.readiness/1",
 "routes": {
  "schemaxis.hdf5/1": {
   "guide": "docs/hdf5.md",
   "context": {
    "purpose": "Create, inspect, audit, extract, edit, compare and exchange HDF5 scientific data files (typed hierarchical datasets, units, scales, compression, links, virtual/external storage, mesh/field series, SWMR acquisition). parallelWrite adds MPI-IO with a parallel h5py build. Unsuitable for remote S3/HDFS reads or third-party filter plugins.",
    "assumptions": "Isolated Python with exactly h5py 3.16.0 (bundled HDF5 2.0.0) and NumPy 2.5.4; HDF Group h5dump 2.2.0 as independent consumer; absolute local inputs captured into the run; row-major values.",
    "constraints": "256 objects, 4M elements per dataset and 16M in total, 65,536-element attributes, rank 8, one-level compound/vlen bases, 1-D scales, 512 MiB sources; MPI on one local machine only (no multi-node), no ros3, filter plugins or arbitrary code.",
    "inspection": "Inspect hdf5-report.json, inventory/expectations/comparison JSON and extracts; host expectations must equal both the fresh h5py readback and the stdlib-parsed h5dump XML, and verify reruns h5dump on current bytes.",
    "recovery": "Correct located INVALID_HDF5_* faults (path, type, value, selection, storage, dimension, edit, extract), configure --hdf5 and --hdf5-h5dump, retain failed evidence and retry in a fresh directory."
   },
   "examples": [
    {
     "id": "sensor-run",
     "reference": "examples/schemaxis/hdf5-sensor-run.json"
    },
    {
     "id": "campaign",
     "reference": "examples/schemaxis/hdf5-campaign.json"
    },
    {
     "id": "inspect",
     "reference": "examples/schemaxis/hdf5-inspect.json"
    },
    {
     "id": "extract",
     "reference": "examples/schemaxis/hdf5-extract.json"
    },
    {
     "id": "edit",
     "reference": "examples/schemaxis/hdf5-edit.json"
    },
    {
     "id": "compare",
     "reference": "examples/schemaxis/hdf5-compare.json"
    },
    {
     "id": "mesh-fields",
     "reference": "examples/schemaxis/hdf5-mesh-fields.json"
    },
    {
     "id": "swmr-monitor",
     "reference": "examples/schemaxis/hdf5-swmr-monitor.json"
    },
    {
     "id": "raw-export",
     "reference": "examples/schemaxis/hdf5-raw-export.json"
    },
    {
     "id": "import-group",
     "reference": "examples/schemaxis/hdf5-import-group.json"
    },
    {
     "id": "streamed-grid",
     "reference": "examples/schemaxis/hdf5-streamed-grid.json"
    },
    {
     "id": "parallel-extract",
     "reference": "examples/schemaxis/hdf5-parallel-extract.json"
    },
    {
     "id": "human-names",
     "reference": "examples/schemaxis/hdf5-human-names.json"
    },
    {
     "id": "filter-rows",
     "reference": "examples/schemaxis/hdf5-filter-rows.json"
    },
    {
     "id": "chunk-index",
     "reference": "examples/schemaxis/hdf5-chunk-index.json"
    },
    {
     "id": "copy-chunks",
     "reference": "examples/schemaxis/hdf5-copy-chunks.json"
    },
    {
     "id": "sieve-columns",
     "reference": "examples/schemaxis/hdf5-sieve-columns.json"
    },
    {
     "id": "large-attributes",
     "reference": "examples/schemaxis/hdf5-large-attributes.json"
    },
    {
     "id": "edit-fields",
     "reference": "examples/schemaxis/hdf5-edit-fields.json"
    },
    {
     "id": "parallel-write",
     "reference": "examples/schemaxis/hdf5-parallel-write.json"
    },
    {
     "id": "invalid-scale-length",
     "reference": "examples/schemaxis/hdf5-invalid-scale-length.json",
     "expect": "invalid",
     "fault": "INVALID_HDF5_DIMENSION",
     "schemaValid": true
    },
    {
     "id": "invalid-int-range",
     "reference": "examples/schemaxis/hdf5-invalid-int-range.json",
     "expect": "invalid",
     "fault": "INVALID_HDF5_VALUE",
     "schemaValid": true
    }
   ],
   "conformance": [
    "tests/unit/test_hdf5.py"
   ],
   "acceptance": [
    "tools/qualify_hdf5.py"
   ],
   "profiles": {
    "workflow": {
     "scope": "HDF5 files, CSV tables, NPY/JSON arrays, XDMF descriptions and reports are verified artifacts for scheduled handoffs; HDF5 file artifacts can be consumed as sources, inputs or dependencies.",
     "references": [
      "docs/hdf5.md",
      "tools/qualify_hdf5.py",
      "examples/schemaxis/hdf5-chain-workflow.json",
      "examples/schemaxis/hdf5-numpy-workflow.json"
     ]
    },
    "composition": {
     "scope": "Shared references, expressions and finite studies resolve to the same literal HDF5 document contract.",
     "references": [
      "docs/hdf5.md",
      "tests/unit/test_hdf5.py"
     ]
    }
   },
   "development": {
    "api": [
     "https://docs.h5py.org/en/stable/high/file.html",
     "https://docs.h5py.org/en/stable/high/group.html",
     "https://docs.h5py.org/en/stable/high/dataset.html",
     "https://docs.h5py.org/en/stable/high/attr.html",
     "https://docs.h5py.org/en/stable/high/dims.html",
     "https://docs.h5py.org/en/stable/special.html",
     "https://docs.h5py.org/en/stable/strings.html",
     "https://docs.h5py.org/en/stable/refs.html",
     "https://docs.h5py.org/en/stable/vds.html",
     "https://docs.h5py.org/en/stable/swmr.html",
     "https://support.hdfgroup.org/documentation/hdf5/latest/",
     "https://www.xdmf.org/index.php/XDMF_Model_and_Format"
    ],
    "lifecycle": {
     "timeout": "Single total deadline across capture, native stages and h5dump (default 300 s, at most 3600 s).",
     "cancellation": "Shared runner cancellation before each stage and a prepublication check.",
     "logs": "Captured inputs/sources/dependencies, authored/plan/native config/payloads/worker/implementation fingerprints, per-stage submissions/stdout/stderr/results and h5dump XML.",
     "verification": "Host expectations from authored intent (generators, rounding, CSV/NPY/raw parsing, selections, edit simulation) compared with a fresh-process h5py readback and HDF Group h5dump 2.2.0 XML parsed by the standard library; verify reruns h5dump on current bytes."
    },
    "data": [
     {
      "id": "hdf5-output",
      "direction": "output",
      "kind": "file",
      "format": "HDF5 (superblock 0/2/3 by libver; sec2/stdio/core/family/split)",
      "traits": {
       "types": "numeric/complex/bool/string/enum/compound/vlen/reference/opaque",
       "units": "units attribute",
       "coordinates": "dimension scales"
      },
      "losses": [
       "No third-party filter plugins or remote drivers; MPI-IO only on one local machine (parallelWrite, parallel extraction); compound/vlen bases one level deep."
      ],
      "scope": "Verified by both consumers."
     },
     {
      "id": "hdf5-source",
      "direction": "input",
      "kind": "file",
      "format": "Existing HDF5 file",
      "traits": {
       "capture": "immutable copy"
      },
      "losses": [
       "Unknown filters, region references and very large datasets are reported or refused rather than reinterpreted."
      ],
      "scope": "inspect/extract/edit/compare sources and dependencies."
     },
     {
      "id": "csv-extract",
      "direction": "output",
      "kind": "table",
      "format": "UTF-8 CSV with quoted header",
      "traits": {
       "header": "name [units]",
       "coordinates": "axis-0 scale column"
      },
      "losses": [
       "No HDF5 type metadata; enum codes as integers; floats as shortest round-trip text."
      ],
      "scope": "extract records in CSV format."
     },
     {
      "id": "npy-json-extract",
      "direction": "output",
      "kind": "file",
      "format": "NPY or JSON arrays",
      "traits": {
       "json": "natural numbers, non-finite as text"
      },
      "losses": [
       "JSON carries a type descriptor but no attributes."
      ],
      "scope": "extract records in npy/json format."
     },
     {
      "id": "xdmf",
      "direction": "output",
      "kind": "file",
      "format": "XDMF 3 XML",
      "traits": {
       "mesh": "unstructured temporal collection"
      },
      "losses": [
       "One HDF5 heavy-data file; cell fields need one cell block."
      ],
      "scope": "writeMeshFields."
     },
     {
      "id": "csv-input",
      "direction": "input",
      "kind": "table",
      "format": "UTF-8 CSV / NPY / raw binary",
      "traits": {
       "header": "required for CSV"
      },
      "losses": [
       "No type inference: the dataset type is declared."
      ],
      "scope": "inputs[] for createFile/editFile/appendSeries."
     }
    ],
    "inspection": [
     {
      "panel": "text",
      "scope": "Inspect hdf5-report.json, inventory.json, expectations.json, comparison.json and extracts.",
      "limits": "No live native file browser."
     }
    ],
    "authoring": {
     "model": "document",
     "example": "sensor-run",
     "reuse": "Every captured byte digest participates in reuse identity; same-path edits invalidate reuse."
    },
    "features": {
     "workflow": {
      "status": "supported",
      "scope": "HDF5 files, CSV tables, NPY/JSON arrays, XDMF descriptions and reports are verified artifacts for scheduled handoffs; HDF5 file artifacts can be consumed as sources, inputs or dependencies."
     },
     "composition": {
      "status": "supported",
      "scope": "Shared references, expressions and finite studies resolve to the same literal HDF5 document contract."
     },
     "reusable-inputs": {
      "status": "supported",
      "scope": "Every captured input, source, reference and dependency byte digest participates in reuse identity."
     },
     "source-authoring": {
      "status": "supported",
      "scope": "Editable typed object, attribute, link, edit, extract and expectation records through common authoring."
     },
     "property-authoring": {
      "status": "supported",
      "scope": "Nested type, data, selection, storage, virtual, dimension and file settings are editable fields."
     },
     "native-save": {
      "status": "supported",
      "scope": "Publish new HDF5 files (createFile, editFile copies, mesh and SWMR series) only after both independent consumers agree."
     },
     "native-inspection": {
      "status": "unsupported",
      "scope": "No interactive native session; inspectFile publishes a verified inventory and expectation decisions."
     },
     "mpi": {
      "status": "unsupported",
      "scope": "Scheduler MPI ranks are not used; parallelWrite and extractData with parallel launch the configured mpiexec on localhost only (shared-memory transport, so an inherited scheduler allocation cannot place ranks on other nodes) with a separately built parallel h5py (mpio driver) and reserve one CPU per rank. Qualified only on one local workstation with 2-3 Open MPI 4.1.7 ranks, not on a cluster or with other MPI implementations. Other operations are serial."
     },
     "time-batches": {
      "status": "unsupported",
      "scope": "No time-list batches; mesh time steps and SWMR batches are declared inside one document."
     },
     "live-editing": {
      "status": "unsupported",
      "scope": "No persistent native state or reverse editing; edits are ordered declarations on captured copies."
     },
     "conversion": {
      "status": "unsupported",
      "scope": "No general format converter; CSV/NPY/raw import and CSV/NPY/JSON extraction are named operations with explicit losses."
     }
    },
    "cases": [
     {
      "id": "sensor-run",
      "example": "sensor-run",
      "edits": [],
      "resources": {},
      "scope": "Baseline typed file: counts are range(-5, 3) in a 6x2 big-endian int16 array, so rows 1-3 are [1,4],[7,10],[13,16]; the attached time scale is linspace(0, 2.5, 6) giving 0.5, 1.0, 1.5 s.",
      "checks": [
       {
        "file": "counts_window.csv",
        "format": "csv",
        "pointer": "/rows",
        "expected": [
         [
          0.5,
          1,
          4
         ],
         [
          1.0,
          7,
          10
         ],
         [
          1.5,
          13,
          16
         ]
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/datasets/~1run~1raw~1counts/shape",
        "expected": [
         6,
         2
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/superblock",
        "expected": 3,
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "campaign",
      "example": "campaign",
      "edits": [],
      "resources": {
       "/inputs/0/path": "examples/schemaxis/hdf5-fixtures/temperatures.csv",
       "/inputs/1/path": "examples/schemaxis/hdf5-fixtures/matrix.npy",
       "/dependencies/0/path": "examples/schemaxis/hdf5-fixtures/run-a.h5",
       "/dependencies/1/path": "examples/schemaxis/hdf5-fixtures/run-b.h5",
       "/dependencies/2/path": "examples/schemaxis/hdf5-fixtures/probe-counts.bin"
      },
      "scope": "Materially different project: run A /signal = 0.5..3.5 fills slots 0-3, run B /signal[1:4] = 5.5..7.5 fills slots 5-7, fill -999 elsewhere; float32 temperatures 293.15..294.5 within float32 relative precision 1e-7.",
      "checks": [
       {
        "file": "stitched.json",
        "format": "json",
        "pointer": "/values",
        "expected": [
         0.5,
         1.5,
         2.5,
         3.5,
         -999.0,
         5.5,
         6.5,
         7.5,
         -999.0,
         -999.0
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "temperature.csv",
        "format": "csv",
        "pointer": "/rows",
        "expected": [
         [
          0.0,
          293.15
         ],
         [
          0.5,
          293.4
         ],
         [
          1.0,
          294.05
         ],
         [
          1.5,
          294.5
         ]
        ],
        "relative": 1e-07,
        "absolute": 0
       }
      ]
     },
     {
      "id": "inspect-vendor",
      "example": "inspect",
      "edits": [],
      "resources": {
       "/source": "examples/schemaxis/hdf5-fixtures/vendor-export.h5"
      },
      "scope": "Adoption of a plain-h5py vendor export (superblock 0): six expectations hold and frames_kelvin is unmet because the frames are in counts. Storage audit: the 4 gzip chunks of 12 logical bytes are stored as 20 bytes each (48 logical, 80 allocated per h5py and h5ls), so frames_compressed is unmet at ratio 0.6.",
      "checks": [
       {
        "file": "expectations.json",
        "format": "json",
        "pointer": "/met",
        "expected": 6,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "expectations.json",
        "format": "json",
        "pointer": "/unmet",
        "expected": 2,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "expectations.json",
        "format": "json",
        "pointer": "/decisions/6/reasons",
        "expected": [
         "units are ['counts']"
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "expectations.json",
        "format": "json",
        "pointer": "/indeterminate",
        "expected": 0,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "expectations.json",
        "format": "json",
        "pointer": "/decisions/7/reasons",
        "expected": [
         "compression ratio 0.6"
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "inventory.json",
        "format": "json",
        "pointer": "/objects/~1acquisition~1frames/storage",
        "expected": {
         "logicalBytes": 48,
         "allocatedBytes": 80,
         "chunks": {
          "count": 4,
          "minBytes": 20,
          "maxBytes": 20,
          "skippedFilters": 0
         }
        },
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "extract-vendor",
      "example": "extract",
      "edits": [],
      "resources": {
       "/source": "examples/schemaxis/hdf5-fixtures/vendor-export.h5"
      },
      "scope": "frames = 10*(6t+3y+x); hyperslab t in {1,3}, y in {0,1}, x in {1,2} gives 70,80,100,110,190,200,220,230; the first-pixel column is 0,60,120,180 against time 0..0.75 ms.",
      "checks": [
       {
        "file": "frame_pixels.json",
        "format": "json",
        "pointer": "/values",
        "expected": [
         70,
         80,
         100,
         110,
         190,
         200,
         220,
         230
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "first_column.csv",
        "format": "csv",
        "pointer": "/rows",
        "expected": [
         [
          0.0,
          0
         ],
         [
          0.25,
          60
         ],
         [
          0.5,
          120
         ],
         [
          0.75,
          180
         ]
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "edit-vendor",
      "example": "edit",
      "edits": [],
      "resources": {
       "/source": "examples/schemaxis/hdf5-fixtures/vendor-export.h5"
      },
      "scope": "Edited copy: the created mean series 25,85,145,205 is attached to the time scale (0..0.75 ms) and extracted with those coordinates.",
      "checks": [
       {
        "file": "mean_counts.csv",
        "format": "csv",
        "pointer": "/rows",
        "expected": [
         [
          0.0,
          25
         ],
         [
          0.25,
          85
         ],
         [
          0.5,
          145
         ],
         [
          0.75,
          205
         ]
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/edits",
        "expected": [
         "setAttribute",
         "write",
         "create",
         "attachScale",
         "copy",
         "move",
         "relayout",
         "renameAttribute"
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "mesh-fields",
      "example": "mesh-fields",
      "edits": [],
      "resources": {},
      "scope": "Two tetrahedra in a 0.1 m cube corner: volumes 1/6 and 1/3 of 0.001 m^3 sum to 5e-4 m^3 with no inverted cell; three XDMF steps.",
      "checks": [
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/mesh/measures/solid/volume",
        "expected": 0.0005,
        "relative": 1e-12,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/mesh/measures/solid/negativeCells",
        "expected": 0,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/xdmf/steps",
        "expected": 3,
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "swmr-monitor",
      "example": "swmr-monitor",
      "edits": [],
      "resources": {},
      "scope": "Batches of 2, 1 and 3 rows of width 3 give cumulative 2, 3 and 6 rows, each observed by both concurrent readers.",
      "checks": [
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/rows",
        "expected": 6,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/writerTimeline",
        "expected": [
         {
          "batch": 0,
          "rows": 2
         },
         {
          "batch": 1,
          "rows": 3
         },
         {
          "batch": 2,
          "rows": 6
         }
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "hdf5-report.json",
        "format": "json",
        "pointer": "/observations",
        "expected": [
         {
          "reader": 0,
          "batchesObserved": 3
         },
         {
          "reader": 1,
          "batchesObserved": 3
         }
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "compare-runs",
      "example": "compare",
      "edits": [],
      "resources": {
       "/source": "examples/schemaxis/hdf5-fixtures/run-a.h5",
       "/reference": "examples/schemaxis/hdf5-fixtures/run-b.h5"
      },
      "scope": "Run A signal 0.5..3.5 and run B 4.5..7.5 differ by 4 V in all four samples (> 0.5 V tolerance); the run attribute differs (a vs b).",
      "checks": [
       {
        "file": "comparison.json",
        "format": "json",
        "pointer": "/equal",
        "expected": false,
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "comparison.json",
        "format": "json",
        "pointer": "/differences",
        "expected": [
         {
          "path": "/meta",
          "kind": "attributes"
         },
         {
          "path": "/signal",
          "kind": "values",
          "count": 4
         }
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "raw-export",
      "example": "raw-export",
      "edits": [],
      "resources": {},
      "scope": "New external raw file: big-endian uint16 range(1000, 250) over two 8-byte segments reads back 1000..2750; float16 keeps 0.5, 1.0, 1.5 and the half-precision maximum 65504; N-bit + gzip chunking on uint32.",
      "checks": [
       {
        "file": "adc.json",
        "format": "json",
        "pointer": "/values",
        "expected": [
         1000,
         1250,
         1500,
         1750,
         2000,
         2250,
         2500,
         2750
        ],
        "relative": 0,
        "absolute": 0
       },
       {
        "file": "gain.json",
        "format": "json",
        "pointer": "/values",
        "expected": [
         0.5,
         1.0,
         1.5,
         65504.0
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "import-group",
      "example": "import-group",
      "edits": [],
      "resources": {
       "/source": "examples/schemaxis/hdf5-fixtures/run-a.h5",
       "/dependencies/0/path": "examples/schemaxis/hdf5-fixtures/vendor-export.h5"
      },
      "scope": "Cross-file copy of a vendor acquisition group: the copied frames keep their copied time scale, so the first-pixel profile 0,60,120,180 carries time 0..0.75 ms.",
      "checks": [
       {
        "file": "imported_first.csv",
        "format": "csv",
        "pointer": "/rows",
        "expected": [
         [
          0.0,
          0
         ],
         [
          0.25,
          60
         ],
         [
          0.5,
          120
         ],
         [
          0.75,
          180
         ]
        ],
        "relative": 0,
        "absolute": 0
       }
      ]
     },
     {
      "id": "parallel-write",
      "example": "parallel-write",
      "edits": [],
      "resources": {},
      "scope": "Two MPI ranks: linspace 300..317 K over 6x3 elements sums to 5553 K (min 300, max 317); cell ids 100+7i for i<7 sum to 847; rank 0 writes rows 0-2 and rank 1 rows 3-5 (temperature) / 3-6 (ids).",
      "checks": [
       {
        "file": "hdf5-report.json",
        "format": "json",
